void populate_metadata(ModelInfo& info, const BackendOpsContext& ctx) const override {
    (void)ctx;
    info.max_context_window = kNativeContext;
}

// Halogen sizes its KV pool itself and maps the checkpoint in place, so the
// router's automatic context, which charges every .hgn file as resident
// weights, would refuse loads that fit. An automatic ctx_size becomes the
// native context before the router sees it.
void resolve_runtime_options(const ModelInfo& info, RecipeOptions& options) const override {
    (void)info;
    const json ctx_size = options.get_option("ctx_size");
    if (!ctx_size.is_number_integer() || ctx_size.get<int>() <= 0) {
        options.set_option("ctx_size", kNativeContext);
    }

std::optional<std::vector<std::string>> select_checkpoint_files(
    const std::string& main_variant, const std::vector<std::string>& repo_files) const override {
    if (!ends_with(main_variant, ".hgn")) {
        return std::nullopt;
    }
    std::vector<std::string> selected;
    for (const auto& file : repo_files) {
        if (file == main_variant || ends_with(file, kLookupTableSuffix) ||
            ends_with(file, kVisionTowerSuffix) ||
            file.rfind(std::string(kTokenizerDir) + "/", 0) == 0) {
            selected.push_back(file);
        }
    }
    if (std::find(selected.begin(), selected.end(), main_variant) == selected.end()) {
        throw std::runtime_error("Halogen checkpoint not found in repository: " + main_variant);
    }
    return selected;

std::optional<utils::SetupFailure> check_container_host(
    const std::string& backend) const override {
    (void)backend;
    const std::string properties = kfd_gpu_properties("gfx1151");
    if (properties.empty()) return std::nullopt;
    return halogen::check_kfd_node(properties);
}

std::optional<utils::SetupFailure> check_kfd_node(const std::string& properties) {
    auto values = parse_kfd_properties(properties);
    if ((values["capability"] & 0x08000000ULL) == 0) {
        return utils::SetupFailure{
            "kernel_svm", "capability & 0x08000000 is 0",
            {"Install Linux 6.18.4 or newer, built with CONFIG_HSA_AMD_SVM"}, ""};
    }
    const bool reported = values.count("cwsr_size") && values.count("ctl_stack_size") &&
                          values.count("simd_count");
    if (!reported || values["cwsr_size"] !=
                         values["ctl_stack_size"] + (values["simd_count"] / 2) * 479232ULL) {
        return utils::SetupFailure{
            "kernel_cwsr", "cwsr_size is not ctl_stack_size + (simd_count / 2) * 479232",
            {"Install Linux 6.18.4 or newer"}, ""};
    }
    return std::nullopt;

if (checkpoint.empty() || !fs::exists(checkpoint)) {
    throw std::runtime_error("halogen: HGN checkpoint not found for model '" + model_name +
                             "' (checkpoint: " + model_info.checkpoint() + ")");
}

// The lookup table, the tokenizer and the optional vision tower sit beside
// the checkpoint in the same snapshot.
const fs::path bundle = fs::path(checkpoint).parent_path();
const std::string table_name = model_info.extra<std::string>("halogen_lookup_table", "");
if (table_name.empty()) {
    throw std::runtime_error("halogen: model '" + model_name +
                             "' names no halogen_lookup_table");
}
const std::string lookup_table = (bundle / table_name).string();
const std::string tokenizer = (bundle / kTokenizerDir).string();
const std::string vision_name = model_info.extra<std::string>("halogen_vision_tower", "");
const std::string vision = vision_name.empty() ? "" : (bundle / vision_name).string();
for (const auto& required : {lookup_table, tokenizer, vision}) {
    if (!required.empty() && !fs::exists(required)) {
        throw std::runtime_error("halogen: the bundle for '" + model_name + "' is missing " +
                                 required);
    }
}

const json ctx_option = options.get_option("ctx_size");
const int ctx_size = ctx_option.is_number_integer() && ctx_option.get<int>() > 0
                         ? ctx_option.get<int>()
                         : kNativeContext;

device_type_ = DEVICE_GPU;

ServerCommand command;
command.model_files = {checkpoint, lookup_table, tokenizer, vision};
command.env = {
    {"HALOGEN_CHECKPOINT", checkpoint},
    {"HALOGEN_NGRAM_TABLE", lookup_table},
    {"HALOGEN_TOKENIZER", tokenizer},
};
if (!vision.empty()) {
    command.env.push_back({"HALOGEN_VISION_TOWER", vision});
}
command.env.insert(command.env.end(), {
    {"HALOGEN_API_PORT", std::to_string(port_)},
    {"HALOGEN_CTX", std::to_string(ctx_size)},
});
command.port = port_;
command.ready_endpoint = "/health";

LOG(INFO, "Halogen") << "Starting " << model_name << " on port " << port_ << std::endl;
const bool inherit_output = (log_level_ == "info") || is_debug();
start_server(std::make_unique<ContainerProcess>(
                 ProcessOutput{inherit_output, true}, halogen::descriptor.recipe, kBackend,
                 model_name, *halogen::descriptor.container_for(kBackend),
                 BackendUtils::get_backend_image(halogen::descriptor.recipe, kBackend)),
             command,
             (std::max)(kStartupTimeoutSeconds, utils::HttpClient::get_default_timeout()));

/*recipe*/          "halogen",
/*display_name*/    "Halogen Flash",
/*binary*/          "",  // the image's entrypoint serves the model
/*config_section*/  "",  // defaults to recipe
/*default_device*/  DEVICE_GPU,
// Halogen is built to own its machine: it sizes its KV pool from MemTotal,
// and the free-memory readings everything else relies on count its pinned
// weights as reclaimable cache.
/*slot_policy*/     SlotPolicy::ExclusiveHost,
/*selectable_backend*/ false,  // rocm is the only backend

// A host-exclusive backend shares the machine with no other local model:
// loading it evicts them all, and loading any other local model evicts it.
// Cloud models hold no local memory and stay.
if (!is_unmetered_recipe(model_info.recipe)) {
    const bool exclusive_load =
        slot_policy_for_recipe(model_info.recipe) == SlotPolicy::ExclusiveHost;
    std::vector<std::pair<WrappedServer*, std::string>> displaced;
    for (const auto& server : loaded_servers_) {
        if (!server->is_backend_alive()) continue;
        const std::string recipe = server->get_recipe_options().get_recipe();
        const SlotPolicy policy = slot_policy_for_recipe(recipe);
        if (policy == SlotPolicy::Unmetered) continue;
        if (!exclusive_load && policy != SlotPolicy::ExclusiveHost) continue;
        const std::string reason =
            (exclusive_load ? model_info.recipe : recipe) + " requires the machine to itself";
        if (should_reject_residency_displacement(requested_residency_class,
                                                 server->get_residency_class())) {
            throw RouterResidencyConflictException(canonical_model_name,
                                                   server->get_model_name(), reason);
        }
        displaced.emplace_back(server.get(), reason);
    }
    for (const auto& [server, reason] : displaced) {
        LOG(INFO, "Router") << reason << ", evicting: " << server->get_model_name()
                            << std::endl;
        evict_server(server);
    }
